import{_ as i,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph on Arm64/Ampere- IOPs/Watt Demystified - Federico Lucifredi, IBM","description":"","frontmatter":{"title":"Ceph on Arm64/Ampere- IOPs/Watt Demystified - Federico Lucifredi, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Arm64","Ampere","Performance","Energy Efficiency"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_on_Arm64_Ampere_-_IOPs_Watt_Demystified_-_Federico_Lucifredi_IBM.md","filePath":"posts/2025/Ceph_on_Arm64_Ampere_-_IOPs_Watt_Demystified_-_Federico_Lucifredi_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_on_Arm64_Ampere_-_IOPs_Watt_Demystified_-_Federico_Lucifredi_IBM.md"};function o(s,e,n,_,u,d){return r(),t("div",null,[...e[0]||(e[0]=[l('<p>本文针对由Federico Lucifredi（IBM代表）在Ceph会议上发表的&quot;Ampere ARM处理器在分布式存储中的性能与能效分析&quot;进行总结。以下为会议要点：</p><h2 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h2><ul><li><strong>主题</strong>：Ampere ARM处理器在Ceph分布式存储中的性能与能效表现</li><li><strong>主讲人</strong>：IBM代表（代Ampere团队分享）</li><li><strong>关键议题</strong>：Ampere Altra与AmpereOne（MR1）处理器在Ceph集群中的IOPS/watt指标对比，探讨ARM架构在Ceph优化潜力。</li></ul><h2 id="核心讨论内容" tabindex="-1">核心讨论内容 <a class="header-anchor" href="#核心讨论内容" aria-label="Permalink to &quot;核心讨论内容&quot;">​</a></h2><h3 id="_1-ampere-arm处理器的ceph性能测试" tabindex="-1">1. Ampere ARM处理器的Ceph性能测试 <a class="header-anchor" href="#_1-ampere-arm处理器的ceph性能测试" aria-label="Permalink to &quot;1. Ampere ARM处理器的Ceph性能测试&quot;">​</a></h3><ul><li><strong>测试目标</strong>：评估IOPS/watt（每瓦特IOPS）作为能效核心指标。</li><li><strong>测试配置</strong>： <ul><li>Ampere Altra：4节点集群（Ubuntu + Quincy），64核/节点，200K IOPS（写入），900W总功耗。</li><li>AmpereOne (MR1)：3节点集群（Ubuntu + Squid），192核/节点，400K IOPS（写入），1430W总功耗。</li><li>其他参数：8 SSDs/OSD，100Gbps网络，replica=2，6000 PGs。</li></ul></li><li><strong>关键发现</strong>： <ul><li>MR1性能翻倍：写入性能从200K → 400K IOPS，IOPS/watt从223 → 285，提升28%。</li><li>线性扩展性：在当前规模（24 OSDs）下未遇到瓶颈，未来计划测试12 OSDs以探索饱和点。</li><li>读性能差异：写入提升2倍，但读取仅1.8倍，需进一步调查。</li></ul></li></ul><h3 id="_2-能效与成本优势" tabindex="-1">2. 能效与成本优势 <a class="header-anchor" href="#_2-能效与成本优势" aria-label="Permalink to &quot;2. 能效与成本优势&quot;">​</a></h3><ul><li><strong>核心价值主张</strong>： <ul><li>降低OPEX：通过高密度核心（192C/节点）减少物理节点数量，优化机架空间与功耗。</li><li>环境可持续性：SSD比HDD更节能（但HDD闲置时功耗更低）。</li></ul></li></ul><h3 id="_3-挑战与未解问题" tabindex="-1">3. 挑战与未解问题 <a class="header-anchor" href="#_3-挑战与未解问题" aria-label="Permalink to &quot;3. 挑战与未解问题&quot;">​</a></h3><ul><li><strong>跨架构对比困难</strong>：与Intel/AMD的公平对比需控制预算（$/性能）而非硬件配置，否则结果易偏颇。</li><li><strong>ARM生态进展</strong>：IBM/Red Hat计划：Ceph Quincy（v16.2）支持ARM客户端，Pacific（v17.2）支持ARM服务端集群。</li></ul><h3 id="_4-后续行动计划" tabindex="-1">4. 后续行动计划 <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. 后续行动计划&quot;">​</a></h3><ul><li><strong>Ampere团队</strong>： <ul><li>扩大测试规模至12 OSDs，验证扩展性上限。</li><li>分析读取性能未达预期的原因。</li></ul></li><li><strong>社区建议</strong>： <ul><li>推广IOPS/watt作为存储集群的TCO评估指标。</li><li>探索单插槽高核数设计对能效的进一步优化。</li></ul></li></ul><h2 id="技术关键词保留" tabindex="-1">技术关键词保留 <a class="header-anchor" href="#技术关键词保留" aria-label="Permalink to &quot;技术关键词保留&quot;">​</a></h2><ul><li><strong>Ceph组件</strong>：OSD, MON, PG, RADOS, CRUSH algorithm</li><li><strong>存储类型</strong>：object storage (RGW), block storage (RBD), file system (CephFS)</li><li><strong>性能相关</strong>：IOPS, latency, replication, erasure coding, tiering</li></ul><h2 id="开放问题" tabindex="-1">开放问题 <a class="header-anchor" href="#开放问题" aria-label="Permalink to &quot;开放问题&quot;">​</a></h2><ul><li><strong>低功耗编码优化</strong>：是否值得为ARM架构重构代码以提升并行性（vs. 单核性能）？ <ul><li>初步反馈：需实测验证，但高核数设计已显优势。</li></ul></li></ul>',16)])])}const p=i(a,[["render",o]]);export{c as __pageData,p as default};
